module ysyx_25020039_Clint(
  input         clock,
                reset,
  input  [31:0] io_araddr,
  input         io_arvalid,
  output        io_arready,
  output [31:0] io_rdata,
  output        io_rvalid,
  input         io_rready
);

  reg [31:0] rdata;
  reg [63:0] mtime;
  reg        state;
  always @(posedge clock) begin
    if (reset) begin
      rdata <= 32'h0;
      mtime <= 64'h0;
      state <= 1'h0;
    end
    else begin
      rdata <= io_araddr == 32'h2000000 ? mtime[31:0] : mtime[63:32];
      mtime <= mtime + 64'h1;
      if (state)
        state <= ~io_rready;
      else
        state <= io_arvalid;
    end
  end // always @(posedge)
  assign io_arready = ~state;
  assign io_rdata = rdata;
  assign io_rvalid = state;
endmodule

